diff --git a/Sources/SwiftJLI/JPEGCodec.swift b/Sources/SwiftJLI/JPEGCodec.swift
index ae1140c..d7130c7 100644
--- a/Sources/SwiftJLI/JPEGCodec.swift
+++ b/Sources/SwiftJLI/JPEGCodec.swift
@@ -245,8 +245,9 @@ enum JPEGCodec {
         let parserBudget = try checkedAdd(checkedMultiply(data.count, 64), 1_048_576)
         try admit(workspace: parserBudget, pixels: 0, compressed: data.count, metadata: 0, limits: limits)
         let bytes = Array(data)
-        let adobeTransform = try JPEGEnvelope.validate(bytes, limits: limits)
-        var reader = MarkerReader(data: bytes)
+        let envelope = try JPEGEnvelope.validate(bytes, limits: limits)
+        let adobeTransform = envelope.adobeTransform
+        var reader = MarkerReader(validated: envelope)
         var parsed = try reader.parse()
         let f = parsed.frameInfo
         if let sourceColourModel {
diff --git a/Sources/SwiftJLI/JPEGEnvelope.swift b/Sources/SwiftJLI/JPEGEnvelope.swift
index 06bb6a2..33820a3 100644
--- a/Sources/SwiftJLI/JPEGEnvelope.swift
+++ b/Sources/SwiftJLI/JPEGEnvelope.swift
@@ -5,12 +5,29 @@ import Foundation
 /// Each segment must fit its own declared extent; bytes in the next segment
 /// cannot satisfy a truncated SOF/SOS/table. Entropy is scanned, never decoded.
 enum JPEGEnvelope {
-    @discardableResult static func validate(_ b: [UInt8], limits: ResourceLimits) throws -> UInt8? {
+    /// Owns the exact immutable bytes whose segment and entropy extents passed
+    /// admission. The private constructor prevents a parser from mixing ranges
+    /// validated against one input with another input. Array value semantics
+    /// retain the owner without making another full-input copy.
+    struct Validated {
+        let bytes: [UInt8]
+        let adobeTransform: UInt8?
+        let entropyRanges: [Range<Int>]
+
+        fileprivate init(bytes: [UInt8], adobeTransform: UInt8?, entropyRanges: [Range<Int>]) {
+            self.bytes = bytes
+            self.adobeTransform = adobeTransform
+            self.entropyRanges = entropyRanges
+        }
+    }
+
+    static func validate(_ b: [UInt8], limits: ResourceLimits) throws -> Validated {
         func malformed() -> CodecError { .init(.malformedInput, "Invalid JPEG marker envelope.") }
         guard b.count >= 4, b[0] == 255, b[1] == 216 else { throw malformed() }
         var p = 2, sawFrame = false, sawScan = false, metadata = 0, iccBytes = 0
         var frameMarker: UInt8 = 0, scanCount = 0
         var adobeTransform: UInt8?
+        var entropyRanges: [Range<Int>] = []
         var iccCount: Int?, iccSequences = Set<Int>(), sawExif = false
         let iccID = Array("ICC_PROFILE\0".utf8), exifID: [UInt8] = [69,120,105,102,0,0]
         while p < b.count {
@@ -30,7 +47,7 @@ enum JPEGEnvelope {
                 if let adobeTransform, (frameMarker == 0xC3 ? adobeTransform != 0 : adobeTransform > 1) {
                     throw CodecError(.unsupportedFeature, "JPEG colour transform is unsupported for this frame.")
                 }
-                return adobeTransform
+                return Validated(bytes: b, adobeTransform: adobeTransform, entropyRanges: entropyRanges)
             }
             guard marker != 0, marker != 216, !(208...215).contains(marker), p + 2 <= b.count else { throw malformed() }
             let length = Int(b[p]) * 256 + Int(b[p + 1])
@@ -131,6 +148,7 @@ enum JPEGEnvelope {
             p = end
             if marker == 0xDA {
                 p = try JPEGEntropyBoundary.find(in: b, from: p)
+                entropyRanges.append(end..<p)
             }
         }
         throw malformed()
diff --git a/Sources/SwiftJLI/Native/Markers/JLIMarkerReader.swift b/Sources/SwiftJLI/Native/Markers/JLIMarkerReader.swift
index f87aa65..a92ac56 100644
--- a/Sources/SwiftJLI/Native/Markers/JLIMarkerReader.swift
+++ b/Sources/SwiftJLI/Native/Markers/JLIMarkerReader.swift
@@ -87,9 +87,19 @@ struct ParsedJPEG: Sendable {
 struct MarkerReader {
     private let data: [UInt8]
     private var offset: Int = 0
+    private let validatedEntropyRanges: [Range<Int>]?
+    private var nextEntropyRange: Int = 0

     init(data: [UInt8]) {
         self.data = data
+        self.validatedEntropyRanges = nil
+    }
+
+    /// Reuses entropy extents from structural admission of these exact bytes.
+    /// Both arrays remain owned values; no pointer or borrow escapes parsing.
+    init(validated: JPEGEnvelope.Validated) {
+        self.data = validated.bytes
+        self.validatedEntropyRanges = validated.entropyRanges
     }

     /// Reads JPEG info without full decode.
@@ -480,7 +490,19 @@ struct MarkerReader {
         // (which paid an Array uniqueness check + growth per byte and showed up
         // at ~7-9% of a whole lossless decode).
         let start = offset
-        let pos = try JPEGEntropyBoundary.find(in: data, from: start)
+        let pos: Int
+        if let ranges = validatedEntropyRanges {
+            guard nextEntropyRange < ranges.count,
+                  ranges[nextEntropyRange].lowerBound == start,
+                  ranges[nextEntropyRange].upperBound <= data.count else {
+                throw JLIError.decodingFailed("Validated entropy extent does not match scan")
+            }
+            try NativeOperation.check()
+            pos = ranges[nextEntropyRange].upperBound
+            nextEntropyRange += 1
+        } else {
+            pos = try JPEGEntropyBoundary.find(in: data, from: start)
+        }
         offset = pos
         return Array(data[start..<pos])
     }
